architecture.h4_f:
msg = CBOR{v:1, mətn, cavab_at, göndərildi}
ct = AES-GCM-256-Şifrələyin(k, heç vaxt, mesaj, aad=otaq_id)
POST /api/rooms/{id}/messages {şifr mətni: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v:1, mətn, cavab_xəbər?, mövzu_id?, qeyd edir?, göndərilən_at}
ct = AES-GCM-256-Şifrələyin(otaq_açarı, heç vaxt, pt, aad=hex(otaq_id))
tel = CBOR{
  v: 1,
  şifrəli mətn: hex(ct), // dəyişən uzunluq
  qeyri: hex(12 B),
  göndərən_psevdo: hex(16 B),
  göndərilən_at: unix_ms
}

cryptoWire.h5_f:
xarici = CBOR{
  mənbə_qovşağı: hex32,
  target_user: int64,
  daxili_şifrə mətni: bayt,
  daxili_nonce: bayt,
  göndərilən_at: unix_ms
}
sig = Ed25519-İşarə(mənbə_priv, xarici)
POST /federasiya/çatdırılma { zərf: xarici, sig: hex64 }

auth.h1_f:
POST /api/identifikasiya/qeydiyyat
  { istifadəçi adı, parol, x25519_public_key, displey_adı, telefon?, e-poçt?, avatar_emoji }

Cavab 201 Yaradıldı:
  { access_token, refresh_token, user_id, username, ...}

auth.h3_f:
access_token yükü:
  { alt: user_id, jti: cihaz_id, yazın: "giriş", eks: indi + 15 dəqiqə }
refresh_token yükü:
  { alt: user_id, jti: cihaz_id, yazın: "yeniləyin", eks: indi + 30 gün }

HS256-.env-dən qovşağın 64 baytlıq sirri ilə imzalanmışdır

auth.h4_f:
register_begin(): problem = rand(32)
                    seçimlər = { rp.id, user.id, pubKeyCredParams, problem }
                    qaytarma variantları

qeydiyyatdan_finish(attestasiya):
  TPM / Təhlükəsiz Anklav kökü CA ilə attestasiyanı yoxlayın
  mağaza {credential_id, public_key, counter: 0}

auth.h7_f:
POST /api/authentication/qr/begin
  → { heç vaxt: 128 bit hex, ttl: 60 }
QR faydalı yük = { heç vaxt, user_id, server: "https://node.example" }

POST /api/authentication/qr/verify { heç vaxt }
  → qeydiyyatdan keçmiş yeni cihaz; JWT-lər geri döndü.

rooms.h6_f:
göndərən_psevdo = HMAC-SHA256(otaq_psevdo_duz, göndərən_id)[:16] // 32 hex
şifrəli mətn = AES-GCM-Şifrələmə(otaq_açarı, birdən-birə, CBOR_payload, aad=otaq_id)

Fan-out çərçivəsi: { type:"m", room, msg:{id, ct, nonnce, sender_pseudo, sent_at} }

files.h2_f:
init POST /api/files/resumable/init {fayl adı, ölçüsü, chunk_size_hint}
            ← {yükləmə_id, yığın_ölçüsü}
yığın PUT /api/files/resumable/{upload_id}/chunk/{ofset} <ct bayt>
            ← 204
yekunlaşdır POST /api/files/resumable/{upload_id}/finalize {plain_blake3}
            ← 201 {fayl_id, url}
TTL tamamlanmamış: 24 saat

calls.h1_f:
POST /api/calls/{room_id}/start {video, audio} → call_id
WS yayım {növü:"c", növ:"invite", zəng_id}
WS yayım {növü:"c", növ:"təklif", sdp}
WS yayım {növü:"c", növ:"cavab", sdp}
WS yayım {növü:"c", növ:"namizəd",buz} × N
POST /api/calls/{call_id}/end

federation.h2_f:
zərf = {
  mənbə_qovşağı: hex32,
  target_user: int64,
  daxili_şifrə mətni: bayt,
  daxili_qeyri: bayt,
  göndərilən_at: unix_ms,
}
sig = Ed25519İmza(mənbə_priv, CBOR(zərf))
POST /federasiya/çatdırılma { zərf, siğ }

stealth.h4_f:
DoH: POST https://cloudflare-dns.com/dns-query {ad: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni(public_key_from_HTTPS_record)
DGA: domen(t) = baza32( SHA256(toxum ∥ YYYY-MM-DD) )[:16] + ".misal"

push.h4_f:
iOS NSE: didReceive(request) { deşifrə(request.content.userInfo) }
Android FCM: onMessageReceived(remoteMessage) { deşifrə(remoteMessage.data) }
Veb SW: self.addEventListener('push', e => şifrəni aç(e.data))

controller.h2_f:
alət = işarə_aləti
giriş = mənbə ağacı, açarlar/release.key
manifest = {
  versiya: "0.1.0",
  qurulmuş_: unix_ms,
  fayllar: [{path, sha256, size}, ...]
}
sig = Ed25519-İmza(release_priv, CBOR(manifest))
çıxış = INTEGRITY.sig.json = {manifest, imzalanmış_tarafından: pub_hex, sig: sig_hex}

bots.h1_f:
yaradın: POST /api/bots {istifadəçi adı, ekran_adı, kod}
          → {bot_id, token, pubkey}
run: in-process (node daxilində korutin)
      OR xarici (uzun sorğu /api/bots/{id}/güncellemeler, token-auth'd)
mesaj: {mətn, imza: Ed25519-İmza(bot_priv, canonical_msg)}

bots.h2_f:
on /start {
  "Xoş gəlmisiniz, {ctx.first_name}" yazın
}
/əlavə <element> {
  state.list = (state.list və ya []) + [ctx.args.item]
  emit "Əlavə edilib: {ctx.args.item}"
}

security.h4_f:
canary.txt (gündəlik):
  {tarix, işarə: Ed25519-İmza(release_priv, tarix)}
müştəri yoxlayır → yoxdur və ya etibarsızdır ⇒ kompromisdən şübhələnir

təcili:
  admin POST /api/admin/revoke-hamısı {səbəb}
  node yayımları {növ:"n", hadisə:"kompromis", səbəb}
  müştərilər açarları silir, yenidən yükləməyə məcbur edir

debugging.h2_f:
dərəcəsi histoqramları (marşrut + metoda görə):
  vortex_http_requests_total{marşrut,metod,status}
  vortex_http_request_duration_seconds_bucket{marşrut,metod,le}

websocket ölçü cihazları:
  vortex_ws_connections{node}
  vortex_ws_fanout_queue_depth{otaq,istifadəçi}

xüsusi sayğaclar:
  vorteks_messages_göndərilən_cəmi{otaq_tipi}
  vorteks_zəngləri_started_total{növ}

